    {
      "keystrokes": "sleep 5\n",
      "duration": 5.0
    },
    {
      "keystrokes": "vncsnapshot -allowblank localhost:1 /tmp/vnc-screenshot3.jpg 2>&1 || true\n",
      "duration": 1.0
    },
    {
      "keystrokes": "python3 -c \"\nfrom PIL import Image\nimg = Image.open('/tmp/vnc-screenshot3.jpg')\nprint('Size:', img.size)\ncolors = img.getcolors(maxcolors=100000)\nprint('Unique colors:', len(colors) if colors else 'more than 100000')\nif colors:\n    top = sorted(colors, key=lambda x: -x[0])[:15]\n    print('Top colors:', top)\n\"\n",
      "duration": 0.5
    },
    {
      "keystrokes": "python3 -c 'import socket, time; s=socket.socket(socket.AF_UNIX, socket.SOCK_STREAM); s.connect(\"/tmp/qemu-monitor.sock\"); s.send(b\"info registers\\n\"); time.sleep(0.5); print(s.recv(8192).decode()); s.close()'\n",
      "duration": 1.0
    }
  ]
